lt_25znqtjnpc02]]},["rlt_25znqtjnpc03"]={["arg1"]=[[添加人物]],["arg2"]=[[25znqwp01b]],["id"]=[[rlt_25znqtjnpc03]]},["rlt_25znqtjnpc04"]={["arg1"]=[[添加人物]],["arg2"]=[[25znqwp02]],["id"]=[[rlt_25znqtjnpc04]]},["rlt_25znqtjnpc05"]={["arg1"]=[[添加人物]],["arg2"]=[[25znqwp02a]],["id"]=[[rlt_25znqtjnpc05]]},["rlt_25znqtjnpc06"]={["arg1"]=[[添加人物]],["arg2"]=[[25znqwp02b]],["id"]=[[rlt_25znqtjnpc06]]},["rlt_25znqtjnpc07"]={["arg1"]=[[添加人物]],["arg2"]=[[25znqwp02c]],["id"]=[[rlt_25znqtjnpc07]]},["rlt_25znqtjnpc08"]={["arg1"]=[[添加人物]],["arg2"]=[[25znqwp02d]],["id"]=[[rlt_25znqtjnpc08]]},["rlt_25znqwb01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李大师：你来得正好，你那玉胚俺刚好完成。NOR]],["id"]=[[rlt_25znqwb01]]},["rlt_25znqwb02"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL李大师：这玉雕最是得专心，那可是一刀一刻都容不得半点儿差池的事，要是一个晃神的工夫，刻错一刀，那这好好的玉胚可就毁了。NOR;YEL李大师：少侠当初雕刻之时，怕是分神了吧。你瞧，就这么错了一刀，便叫这青龙势减三分。NOR;YEL李大师：倒也不是没有补救之法，只不过这个法子更需细心，少侠可愿做？NOR]],["arg3"]=[[1;1;1]],["id"]=[[rlt_25znqwb02]]},["rlt_25znqwb03"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李大师：好，少侠明日再来，俺还要做些个准备。NOR]],["id"]=[[rlt_25znqwb03]]},["rlt_25znqwb04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李大师：俺还得在这待上几日，下月之前，少侠要是改了主意，随时来找。NOR]],["id"]=[[rlt_25znqwb04]]},["rlt_25znqwb05"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李大师：少侠来了，那咱便开始吧。NOR]],["id"]=[[rlt_25znqwb05]]},["rlt_25znqwb06"]={["arg1"]=[[副本故事]],["arg2"]=[[CYN你按照李大师的指导修补雕像。NOR;CYN每一步都很细致，你不敢分神。NOR;CYN直到你的眼睛开始酸涩，李大师才叫停你。NOR]],["arg3"]=[[2;2;2]],["id"]=[[rlt_25znqwb06]]},["rlt_25znqwb07"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李大师：专心一致，万事可成，少侠你看，这不就成了。NOR]],["id"]=[[rlt_25znqwb07]]},["rlt_25znqwb08"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL李大师：这玉雕最是得专心，那可是一刀一刻都容不得半点儿差池的事，要是一个晃神的工夫，刻错一刀，那这好好的玉胚可就毁了。NOR;YEL李大师：少侠当初雕刻之时，实在是不专心啊，这少刻几分，那多刻两刀，这玉雕可不就毁了。NOR;YEL李大师：倒也不是没有补救之法，只不过这个法子更需细心，少侠可愿做？NOR]],["arg3"]=[[1;1;1]],["id"]=[[rlt_25znqwb08]]},["rlt_25znqwp01"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[25znqhome01]],["arg3"]=1,["id"]=[[rlt_25znqwp01]]},["rlt_25znqwp02"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[25znqhome02]],["arg3"]=1,["id"]=[[rlt_25znqwp02]]},["rlt_25znqwp03"]={["arg1"]=[