daddnpc01"]={["arg1"]=[[随机人物投放]],["arg2"]=[[fbnpc46]],["arg3"]=[[fb221_01;fb221_03;fb221_05;fb221_08;fb221_09;fb221_10;fb221_11;fb221_12;fb221_13;fb221_14;fb221_15;fb221_16;fb221_17;fb221_18;fb221_19;fb221_20;fb221_21;fb221_23;fb221_24;fb221_25;fb221_26;fb221_27;fb221_28;fb221_29;fb221_30;fb221_31;fb221_32;fb221_34;fb221_35;fb221_36;fb221_37;fb221_38;fb221_39;fb221_40;fb221_41;fb221_42]],["id"]=[[rlt_fbrdaddnpc01]]},["rlt_fbrdaddnpc02"]={["arg1"]=[[随机人物投放]],["arg2"]=[[fbnpc47]],["arg3"]=[[fb221_01;fb221_03;fb221_05;fb221_08;fb221_09;fb221_10;fb221_11;fb221_12;fb221_13;fb221_14;fb221_15;fb221_16;fb221_17;fb221_18;fb221_19;fb221_20;fb221_21;fb221_23;fb221_24;fb221_25;fb221_26;fb221_27;fb221_28;fb221_29;fb221_30;fb221_31;fb221_32;fb221_34;fb221_35;fb221_36;fb221_37;fb221_38;fb221_39;fb221_40;fb221_41;fb221_42]],["id"]=[[rlt_fbrdaddnpc02]]},["rlt_fbrewardlevel1"]={["arg1"]=[[策略奖励]],["arg2"]=[[wulinrewardlv1]],["id"]=[[rlt_fbrewardlevel1]]},["rlt_fbrewardlevel2"]={["arg1"]=[[策略奖励]],["arg2"]=[[wulinrewardlv2]],["id"]=[[rlt_fbrewardlevel2]]},["rlt_fbrewardlevel3"]={["arg1"]=[[策略奖励]],["arg2"]=[[wulinrewardlv3]],["id"]=[[rlt_fbrewardlevel3]]},["rlt_fbrewardlevel4"]={["arg1"]=[[策略奖励]],["arg2"]=[[wulinrewardlv4]],["id"]=[[rlt_fbrewardlevel4]]},["rlt_fbstory01"]={["arg1"]=[[副本故事]],["arg2"]=[[你踏足天都绝顶，只觉青云聚于顶上，浩然之气飘于四方，真可谓：任他五岳归来客，一见天都也叫奇。;此时中原武林中的各门派首脑汇于天都绝顶。盛举空前，正、中、邪三方三足鼎立，召开牵涉这一代中原武林命运的“武林盟会”。]],["arg3"]=[[2;2]],["id"]=[[rlt_fbstory01]]},["rlt_fbstory02"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL圆悲大师：阿弥陀佛。既然各位武林同道已聚齐，事态紧急，还问各位同道有何建议？既是为中原武林发声，无论正邪高低，但说无妨。;YEL宝相神尼：既为盟友，当设盟规。贫尼认为，凡中原武林弟子，应当守望相助，共抗外敌。就算有新仇旧怨，也不可自相残杀。;YEL宝相神尼：这第一条盟规，任施主、仇施主，二位意下如何？;YEL仇穆仲：哼！既然宝相神尼发话，仇某自当听从。;YEL任天南：好！我伏龙山也无二话。;YEL圆悲大师：阿弥陀佛。二位施主能放下恩怨，实属中原武林之幸。既如此，这第一条盟规算是定下了。]],["arg3"]=[[2;2;2;2;2;2]],["id"]=[[rlt_fbstory02]]},["rlt_fbstory03"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL上官羽：我们做生意的，要讲以和为贵。若是二位掌门真的放下恩怨，那自然再好不过。若是私下磕磕碰碰，那也无可厚非。;YEL任天南：财神帮的小子，你说这话是什么意思？;YEL上官羽：呵呵，任帮主别生气。在下的意思是：江湖子弟不妨都是血气方刚之辈，若是仇不能报，耻不能雪，岂不自磨锐气？;YEL上官羽：依我之见，不得残杀同胞是真，但却无碍武林同道相互切磋比斗。;YEL上官羽：我提议，由我财神帮出资建设擂台和试炼。各位同道将前耻旧恨化为动力，在擂台上切磋学习，在试炼场较量竞技，岂不是好事一桩？;YEL慕容业：上官兄好魄力。我龙城山庄赞成。不过光有比武，没有文试怎么行？;YEL欧阳啸：呵呵，慕容兄说的是，江湖同道切磋，既要比武，也要比文才是。不若再加个文试如何？;YEL丁香：此举可行，只是让上官兄破费了。;YEL上官羽：能为中原武林做贡献，亦有利于我帮的名誉。还请各位同道不要客气。这文试楼，也由我一并包办吧。;YEL圆悲大师：好。既然各位都赞成，那此事就有劳上官施主办理了。]],["arg3"]=[[2;2;2;2;2;2;2;2;2;2]],["id"]=[[rlt_fbstory03]]},["rlt_fbstory04"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL江上游：老乞丐我没文化也没仇人，文试武斗老乞丐都不在乎，只求为中原武林多做贡献。哎哟…我的肚子…;YEL杨秋白：老乞丐说的好。我认为应当设立堂口，为武林盟弟子颁发任务和奖励，让大家为我们武林盟多做贡献。这才是有意义之事。;YEL百晓生：哈哈哈！有生之年能参加这武林盟会，可谓三生有幸啊。小生忙于生计，不曾为江湖付出什么。惭愧惭愧，不如这武林盟任务，就由百晓堂代劳吧。;YEL圆悲大师：阿弥陀佛，此事交于百晓生施主，再好不过。]],["arg3"]=[[2;2;2;2]],["id"]=[[rlt_fbstory04]]},["rlt_fbstory05"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL欧阳博：杂事都谈完了吧？接下来，我们是不是该谈谈正事了？;YEL圆悲大师：敢问欧阳施主？何为杂事？何为正事？;YEL欧阳博：圆悲大师不知是真糊涂还是装糊涂？这正事，自然是决定这武林盟主之位。;YEL莫血衣：呵呵，欧阳博，就凭你也想来争武林盟主？;YEL欧阳博：不错。我不像你们这帮正人君子，我有话喜欢直说。还有谁要争着武林盟主之位的，一起站出来吧！;YEL宝相神尼：欧阳施主忘了刚才的第一条盟规了吗？凡武林盟弟子应当守望相助，为了一虚名而刀剑相向实在有悖盟意，武林盟主一事休要再提。;YEL？？？：嘻嘻嘻…既然没人要当武林盟主，那不如就让给我当吧！;YEL张松溪：嗯？坏了！是重光教的人！武当弟子，速速结阵！;YEL武当弟子：是！]],["arg3"]=[[2;2;2;2;2;2;2;2]],["id"]=[[rlt_fbstory05]]},["rlt_fbstory06"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL上官羽：这几日建造师傅们马不停蹄，加急赶工，现在已经又饿又渴了。;YEL上官羽：若是少侠下山去的话，不妨去衡阳的回雁楼捎一壶陈年女儿香回来，给师傅们解解渴。]],["arg3"]=[[2;2]],["id"]=[[rlt_fbstory06]]},["rlt_fbstory07"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL上官羽：这几日建造师傅们马不停蹄，加急赶工，现在已经又饿又渴了。;YEL上官羽：若是少侠下山去的话，不妨去扬州城的松鹤楼捎一只烧鸡回来，给师傅们解解馋。]],["arg3"]=[[2;2]],["id"]=[[rlt_fbstory07]]},["rlt_fbstory08"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL上官羽：这琼楼庙宇即日便要建成，但建造师傅却说少了一种石材。;YEL上官羽：这缺少的石材便是雨花石，麻烦少侠将这雨花石带一块回来。]],["arg3"]=[[2;2]],["id"]=[[rlt_fbstory08]]},["rlt_fbstory09"]={["arg1"]=[[副本故事]],["id"]=[[rlt_fbstory09]]},["rlt_fbstory10"]={["arg1"]=[[副本故事]],["id"]=[[rlt_fbstory10]]},["rlt_fbtext01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL武林盟弟子：阁下好身手！]],["id"]=[[rlt_fbtext01]]},["rlt_fbtext02"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL武林盟弟子：站住！验明身份后方可上山。]],["id"]=[[rlt_fbtext02]]},["rlt_fbtext03"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL武林盟弟子：原来是少侠。恕我等眼拙，还请少侠快快入内。]],["id"]=[[rlt_fbtext03]]},["rlt_fbtext04"]={["arg1"]=[[文本输出]],["arg2"]=[[你走到这狭隘的山口，只见前方站着三个人，气氛十分凝重。]],["id"]=[[rlt_fbtext04]]},["rlt_fbtext05"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL邢天涯：哼！若不是有人阻挠，我今天定要他人头落地！]],["id"]=[[rlt_fbtext05]]},["rlt_fbtext06"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL任贤：好好好，今日有人拦着，下次任某再来和你一决生死！]],["id"]=[[rlt_fbtext06]]},["rlt_fbtext07"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL张松溪：这里先交给我们吧。少侠快去天都石室看看，我担心有不好的事发生。]],["id"]=[[rlt_fbtext07]]},["rlt_fbtext08"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL欧阳博：唐不平，你的蹩脚毒术练得如何？来来来，我们看谁先毒倒那个番婆子。]],["id"]=[[rlt_fbtext08]]},["rlt_fbtext09"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐不平：欧阳老鬼，说话客气点，小心我失手要了你一对招子。]],["id"]=[[rlt_fbtext09]]},["rlt_fbtext10"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL莫血衣：不好，天都石室怕是…]],["id"]=[[rlt_fbtext10]]},["rlt_fbtext11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL圆悲大师：阿弥陀佛，我等在此守住，还请施主速去天都石室看守。]],["id"]=[[rlt_fbtext11]]},["rlt_fbtext12"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL宝相神尼：倚天一出，谁与争锋？尔等区区十二人，还是速速离去吧。]],["id"]=[[rlt_fbtext12]]},["rlt_fbtext13"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL江上游：哎哟，我的肚子啊…]],["id"]=[[rlt_fbtext13]]},["rlt_fbtext14"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL杨秋白：臭要饭的，你没事吧？]],["id"]=[[rlt_fbtext14]]},["rlt_fbtext15"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL任天南：难道这天都石室，是藏了什么秘密不成？]],["id"]=[[rlt_fbtext15]]},["rlt_fbtext16"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL仇穆仲：看那白毛鬼，嘿嘿，长得跟熊一样。]],["id"]=[[rlt_fbtext16]]},["rlt_fbtext17"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL萧逸龙：他们是冲着天都石室去的，快派人去看看！]],["id"]=[[rlt_fbtext17]]},["rlt_fbtext18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL慕容业：哦？重光教的人中居然还有中原人？有趣。]],["id"]=[[rlt_fbtext18]]},["rlt_fbtext19"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL张胜岱：我本想静观其变，看来不行了。]],["id"]=[[rlt_fbtext19]]},["rlt_fbtext20"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL塞索斯：我从那几个中原人的身上，闻到了猛兽的味道。]],["id"]=[[rlt_fbtext20]]},["rlt_fbtext21"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL什纳罗：我是来替你们赎罪的。]],["id"]=[[rlt_fbtext21]]},["rlt_fbtext22"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL立花忠信：盛贤，中原人的茶道与剑道，值得我们学习。]],["id"]=[[rlt_fbtext22]]},["rlt_fbtext23"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李盛贤： 哼。]],["id"]=[[rlt_fbtext23]]},["rlt_fbtext24"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL波罗洛夫：来啊！让我敲碎你们的头颅！]],["id"]=[[rlt_fbtext24]]},["rlt_fbtext25"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL莱恩：别担心，卡米尔，我会保护你的。]],["id"]=[[rlt_fbtext25]]},["rlt_fbtext26"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL卡米尔：莱恩…你真是…]],["id"]=[[rlt_fbtext26]]},["rlt_fbtext27"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL罗兰：哈哈哈哈！中原的朋友们别紧张，我们就是来玩玩的！]],["id"]=[[rlt_fbtext27]]},["rlt_fbtext28"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL库利亚：开天辟地，日月重光。只有重光教才能拯救世界。]],["id"]=[[rlt_fbtext28]]},["rlt_fbtext29"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL瓦尔塔：把你们，都埋葬。]],["id"]=[[rlt_fbtext29]]},["rlt_fbtext30"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL沐言华：中原，我们又回来了啊…]],["id"]=[[rlt_fbtext30]]},["rlt_fbtext31"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL沐言薇：哥！你别得意忘形了。]],["id"]=[[rlt_fbtext31]]},["rlt_fbtext32"]={["arg1"]=[[文本输出]],["arg2"]=[[你来到天都石室洞口，看到一男一女，一大一小，两人正从石室中出来。中年男人是西洋人，小女孩却是中原人。]],["id"]=[[rlt_fbtext32]]},["rlt_fbtext33"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL劳伦斯：哈哈哈！有趣！我记住你了，我们会再见面的。]],["id"]=[[rlt_fbtext33]]},["rlt_fbtext34"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL圆悲大师：阿弥陀佛。这一天终于还是来了。施主辛苦了。今后，中原武林怕是难有安宁之日了。]],["id"]=[[rlt_fbtext34]]},["rlt_fbtext35"]={["arg1"]=[[文本输出]],["arg2"]=[[只见原本聚集在峰顶的众人不知何时散去，留下区区几人。而圆悲大师留在原地，挥手唤你过去。]],["id"]=[[rlt_fbtext35]]},["rlt_fbtext36"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL圆悲大师：施主请留步。]],["id"]=[[rlt_fbtext36]]},["rlt_fbtext37"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL燕云天：除非受到圆悲大师的准许，否则任何人都不得进入天都石室。]],["id"]=[[rlt_fbtext37]]},["rlt_fbtext38"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL上官羽：少侠再多等几日吧。在这山峰上建设文无第一庙和独求一败楼，还需要些时日。]],["id"]=[[rlt_fbtext38]]},["rlt_fbtext39"]={["arg1"]=[[文本输出]],["arg2"]=[[盘空千万仭，险若上丹梯；
调入天都里，回看鸟道低。
他山青点点，远水白凄凄；
欲下前峰瞑，岩间宿锦鸡。]],["id"]=[[rlt_fbtext39]]},["rlt_fbtext40"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL风来晚：此处的厢房已经被人定了。还请少侠下次再来。]],["id"]=[[rlt_fbtext40]]},["rlt_fbtext41"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL江上游：真想大吃大喝一顿。]],["id"]=[[rlt_fbtext41]]},["rlt_fbtext42"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL江上游：老乞丐的肚子太饿了。听说在这天都峰上有一座中华阁，老板所做的名菜云中雀可谓当今一流，快帮我买一份回来吧。]],["id"]=[[rlt_fbtext42]]},["rlt_fbtext43"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL江上游：唔，好吃，好吃。咦？我怎么看到了观音菩萨？]],["id"]=[[rlt_fbtext43]]},["rlt_fbtext44"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL重光密探：哦？被发现了？这里的中原高手太多，被抓到就完了！快跑！]],["id"]=[[rlt_fbtext44]]},["rlt_fbtext45"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL永夜：来这武林盟随便逛逛，还能顺便尝一尝云老板的菜品，真是不错。]],["id"]=[[rlt_fbtext45]]},["rlt_fbtext46"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL云沧海：嗯…永夜楼主到了。还请少侠替我将这盘云中栗转交于她。]],["id"]=[[rlt_fbtext46]]},["rlt_fbtext47"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL云沧海：永夜楼主来无影去无踪，劳烦少侠尽快找找了。]],["id"]=[[rlt_fbtext47]]},["rlt_fbtext48"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL云沧海：少侠没找着永夜楼主？莫不是已经走了，晚点再来看看吧。]],["id"]=[[rlt_fbtext48]]},["rlt_fbtext49"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL云沧海：想要点什么自己看吧。]],["id"]=[[rlt_fbtext49]]},["rlt_fbtext50"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL云沧海：这里的伙计不多，只我和风师弟二人而已。]],["id"]=[[rlt_fbtext50]]},["rlt_fbtext51"]={["arg1"]=[[文本输出]],["arg2"]=[[你一个不慎从高处摔了下来。摔成了重伤。]],["id"]=[[rlt_fbtext51]]},["rlt_fbtext52"]={["arg1"]=[[文本输出]],["arg2"]=[[你来回穿梭，身轻如燕，攀到了绝壁之上。
极目远望，云山相接，江河一线；俯瞰群山，千峰竞秀，巧石献奇。若烟云乍起，披霞驭风，如入仙境。
