"]={["arg1"]=[[结果集]],["arg2"]=[[sy4text02;sy4renwubj02;sy4change05]],["id"]=[[rlt_sy4jiujgj02]]},["rlt_sy4jiujgj03"]={["arg1"]=[[结果集]],["arg2"]=[[sy4text04;sy4renwubj02b;sy4change07]],["id"]=[[rlt_sy4jiujgj03]]},["rlt_sy4jiujgj04"]={["arg1"]=[[结果集]],["arg2"]=[[sy4text05;syrenwujieshubj;syrenwujindubj04;sy4renwubj02c;sy4change08]],["id"]=[[rlt_sy4jiujgj04]]},["rlt_sy4jtbj06"]={["arg1"]=[[地图标记设置]],["arg2"]=[[21手艺人白秋笙遇险]],["arg3"]=1,["id"]=[[rlt_sy4jtbj06]]},["rlt_sy4money01"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[money]],["arg3"]=-50,["id"]=[[rlt_sy4money01]]},["rlt_sy4money02"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[money]],["arg3"]=-5000,["id"]=[[rlt_sy4money02]]},["rlt_sy4renwubj01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人去买烧鸡]],["arg3"]=1,["id"]=[[rlt_sy4renwubj01]]},["rlt_sy4renwubj01q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人去买烧鸡]],["id"]=[[rlt_sy4renwubj01q]]},["rlt_sy4renwubj02"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人送烧鸡]],["arg3"]=1,["id"]=[[rlt_sy4renwubj02]]},["rlt_sy4renwubj02b"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人送烧鸡]],["arg3"]=2,["id"]=[[rlt_sy4renwubj02b]]},["rlt_sy4renwubj02c"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人送烧鸡]],["arg3"]=3,["id"]=[[rlt_sy4renwubj02c]]},["rlt_sy4renwubj02cq"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人送烧鸡]],["id"]=[[rlt_sy4renwubj02cq]]},["rlt_sy4renwubj03"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人拒绝买烧鸡]],["arg3"]=1,["id"]=[[rlt_sy4renwubj03]]},["rlt_sy4renwubj03q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人拒绝买烧鸡]],["id"]=[[rlt_sy4renwubj03q]]},["rlt_sy4renwubj07"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人给钱平事]],["arg3"]=1,["id"]=[[rlt_sy4renwubj07]]},["rlt_sy4renwubj07q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人给钱平事]],["id"]=[[rlt_sy4renwubj07q]]},["rlt_sy4renwubj08"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人出手教训]],["arg3"]=1,["id"]=[[rlt_sy4renwubj08]]},["rlt_sy4renwubj08q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人出手教训]],["id"]=[[rlt_sy4renwubj08q]]},["rlt_sy4renwubj10"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人质疑后提交枣木]],["arg3"]=1,["id"]=[[rlt_sy4renwubj10]]},["rlt_sy4renwubj10q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人质疑后提交枣木]],["id"]=[[rlt_sy4renwubj10q]]},["rlt_sy4songli01"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[syiteams05,1]],["arg3"]=[[sy4jiujgj02]],["arg4"]=[[sy4text22]],["id"]=[[rlt_sy4songli01]]},["rlt_sy4songli02"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[syiteams05,1]],["arg3"]=[[sy4jiujgj03]],["arg4"]=[[sy4text22]],["id"]=[[rlt_sy4songli02]]},["rlt_sy4songli03"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[syiteams05,1]],["arg3"]=[[sy4jiujgj04]],["arg4"]=[[sy4text22]],["id"]=[[rlt_sy4songli03]]},["rlt_sy4text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL你如约来此，见白秋笙此时正倚靠在藤椅上看书。]],["id"]=[[rlt_sy4text01]]},["rlt_sy4text02"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：怎么去了这么久？鸡都凉了！叫我怎么吃？再去买一只！这次速度快点！]],["id"]=[[rlt_sy4text02]]},["rlt_sy4text03"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：你这家伙！真是孺子不可教也！]],["id"]=[[rlt_sy4text03]]},["rlt_sy4text04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙： 嗯，这次买的虽然不凉，但味道不对！再去重买一只！]],["id"]=[[rlt_sy4text04]]},["rlt_sy4text05"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：嗯，这回买的味道和温度倒是对了，就是有点咸。嗝...咳咳，今天就先到这吧，老夫身体有些不舒服要休息了，明日你再来此，老夫传授你一些技法。]],["id"]=[[rlt_sy4text05]]},["rlt_sy4text06"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL孙勇：今天又卖了不少酒钱，哈哈哈，看来我这自制杜康销量还是不错的呀！
YEL陈南：我说老孙，你自制的东西真的没问题么？别被举报了抓进衙门。
YEL孙勇：我说老陈，你能不能不碎嘴？还好意思说我，你那土质烧鸡用的什么料还用我说么？
YEL陈南：你说，如果有人吃了我的鸡，又喝了你的酒，那会怎样？
YEL孙勇：不知道...估计好不了...]],["id"]=[[rlt_sy4text06]]},["rlt_sy4text07"]={["arg1"]=[[文本输出]],["arg2"]=[[你如约来此，见白秋笙此时正准备从院内用杂物将门封堵。]],["id"]=[[rlt_sy4text07]]},["rlt_sy4text08"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL白秋笙：愣着干什么？赶紧帮老夫堵门！;CYN正当你挪过来一个木架时，院门被一脚踹开，随之走进来一个肌肉发达的黑脸汉子。;YEL黑脸汉子：老头！欠我们孙老爷的钱是不是该还了？]],["arg3"]=[[2;2;2]],["id"]=[[rlt_sy4text08]]},["rlt_sy4text09"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：你这莽夫！老夫光明磊落何时欠了你们钱？
YEL黑脸汉子：哦？这么说是我们孙老爷诬赖你喽？少废话，今天不交钱，老子把你这破房子拆了！]],["id"]=[[rlt_sy4text09]]},["rlt_sy4text10"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL黑脸汉子：看什么看？没事赶紧给老子滚！]],["id"]=[[rlt_sy4text10]]},["rlt_sy4text11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL黑脸汉子：快给钱！]],["id"]=[[rlt_sy4text11]]},["rlt_sy4text12"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：唉，前几日为了避雨，不小心碰坏了孙府挂在门口的灯笼。可这厮张口就要五千两，简直就是强盗！今日此般场面，不如徒儿你...]],["id"]=[[rlt_sy4text12]]},["rlt_sy4text13"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL黑脸汉子：哦？看你年纪轻轻想不到出手如此大方，在下佩服。今日之事就此了结，老人家，以后出门在外小心着点，可别又碰坏了什么赔不起的东西，到时候还得麻烦我们跑一趟。
YEL白秋笙：啊呸！狗仗人势的东西，这分明就是讹诈！
YEL白秋笙：哼！多管闲事！你拿钱给他们不是助长他们这些歪风邪气么！你先回去吧！教你手艺的事明日来了再说，老夫定要去官府告他一状！]],["id"]=[[rlt_sy4text13]]},["rlt_sy4text14"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL黑脸汉子：哦？就凭你也想给这老家伙出头？今天就让你知道知道什么叫做沙包一样大的拳头！]],["id"]=[[rlt_sy4text14]]},["rlt_sy4text15"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL黑脸汉子：呸！多管闲事的家伙！今天就先放过你，你给老子记住了！早晚有一天跟你算这笔帐！
YEL白秋笙：教训的好！让这群欺软怕硬的懦夫长长记性！今日你先回去，等老夫准备准备必要去官府告他一状，明日你再前来，老夫传授你手艺。]],["id"]=[[rlt_sy4text15]]},["rlt_sy4text16"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：你还留这做什么？还不快回去？等老夫收拾收拾就去官府！明日你再来此！]],["id"]=[[rlt_sy4text16]]},["rlt_sy4text17"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：你先回去吧，明日再来。]],["id"]=[[rlt_sy4text17]]},["rlt_sy4text18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：哦？你还知道来呀？昨日我交代你的枣木收集好了么？]],["id"]=[[rlt_sy4text18]]},["rlt_sy4text19"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：哼，看来你对学习手艺这件事根本不用心！你以为制作手艺品是很简单的的么！无知！]],["id"]=[[rlt_sy4text19]]},["rlt_sy4text20"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：你给我站住！你这目中无人，不懂得尊师重道的小辈！]],["id"]=[[rlt_sy4text20]]},["rlt_sy4text21"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：真是胡闹！传统手艺技法就是因为有你们这种轻浮之辈才没落至今！老夫真是看错人了！]],["id"]=[[rlt_sy4text21]]},["rlt_sy4text22"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙:我的烧鸡呢！]],["id"]=[[rlt_sy4text22]]},["rlt_sy4text23"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN书信内容：既然你如此厌烦老夫这门手艺，老夫便也不强人所难。这箱中的墨璃珠你拿着去老人峰找刘南春换取你需要的东西吧，如果还需此物不妨去刘南春旁边的秦高松那问问。]],["id"]=[[rlt_sy4text23]]},["rlt_sy4text24"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL黑脸汉子：没钱还学别人逞英雄！]],["id"]=[[rlt_sy4text24]]},["rlt_sy4textout01"]={["arg1"]=[[弹出文本]],["arg2"]=[[不好意思，客官。原味烧鸡卖完了。]],["id"]=[[rlt_sy4textout01]]},["rlt_sy4textout02"]={["arg1"]=[[文本输出]],["arg2"]=[[客官，带够钱再来吧！]],["id"]=[[rlt_sy4textout02]]},["rlt_sy5addnpc01"]={["arg1"]=[[添加人物]],["arg2"]=[[sy5npc_01]],["id"]=[[rlt_sy5addnpc01]]},["rlt_sy5addnpc02"]={["arg1"]=[[添加人物]],["arg2"]=[[sy5npc_01a]],["id"]=[[rlt_sy5addnpc02]]},["rlt_sy5addnpc06"]={["arg1"]=[[添加人物]],["arg2"]=[[sy5npc_01b]],["id"]=[[rlt_sy5addnpc06]]},["rlt_sy5change01"]={["arg1"]=[[换人]],["arg2"]=[[sy5npc_01]],["arg3"]=[[sy5npc_01a]],["id"]=[[rlt_sy5change01]]},["rlt_sy5change07"]={["arg1"]=[[换人]],["arg2"]=[[sy5npc_01a]],["arg3"]=[[sy5npc_01b]],["id"]=[[rlt_sy5change07]]},["rlt_sy5gushi01"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL白秋笙：制作脸谱技法中最为重要的一点即为上色，优质的颜料可以更好的表现作品本身的魅力。;YEL白秋笙：你今日就去扬州城十里长街处，寻找一位名叫阿珍的优伶。她培育的杜鹃花可以调制出品质上乘的颜料。你去讨要一些，切记要谨言慎行。]],["arg3"]=[[2;2]],["id"]=[[rlt_sy5gushi01]]},["rlt_sy5renwubj01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人买杜鹃花任务]],["arg3"]=1,["id"]=[[rlt_sy5renwubj01]]},["rlt_sy5renwubj01q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人买杜鹃花任务]],["id"]=[[rlt_sy5renwubj01q]]},["rlt_sy5renwubj02q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人夸赞阿珍]],["id"]=[[rlt_sy5renwubj02q]]},["rlt_sy5renwubj03q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人对阿珍说实话]],["id"]=[[rlt_sy5renwubj03q]]},["rlt_sy5renwubj04q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人送阿珍莲子糕]],["id"]=[[rlt_sy5renwubj04q]]},["rlt_sy5renwubj05q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人给阿珍赔钱]],["id"]=[[rlt_sy5renwubj05q]]},["rlt_sy5renwubj06q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人杜鹃花]],["id"]=[[rlt_sy5renwubj06q]]},["rlt_sy5text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：嗯，不错，今日还算准时。]],["id"]=[[rlt_sy5text01]]},["rlt_sy5text03"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：嗯，既然原料明天才能送来那你今天就先回去吧。]],["id"]=[[rlt_sy5text03]]},["rlt_sy5text04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：阿珍在扬州城的十里长街，你去到此处访问便可。]],["id"]=[[rlt_sy5text04]]},["rlt_sy6addnpc01"]={["arg1"]=[[添加人物]],["arg2"]=[[sy6npc_01]],["id"]=[[rlt_sy6addnpc01]]},["rlt_sy6addnpc02"]={["arg1"]=[[添加人物]],["arg2"]=[[sy6npc_02]],["id"]=[[rlt_sy6addnpc02]]},["rlt_sy6addnpc03"]={["arg1"]=[[添加人物]],["arg2"]=[[sy6npc_07b]],["id"]=[[rlt_sy6addnpc03]]},["rlt_sy6addnpc04"]={["arg1"]=[[添加人物]],["arg2"]=[[sy6npc_08]],["id"]=[[rlt_sy6addnpc04]]},["rlt_sy6addnpc05"]={["arg1"]=[[添加人物]],["arg2"]=[[sy6npc_01a]],["id"]=[[rlt_sy6addnpc05]]},["rlt_sy6addnpc06"]={["arg1"]=[[添加人物]],["arg2"]=[[sy6npc_01b]],["id"]=[[rlt_sy6addnpc06]]},["rlt_sy6change01"]={["arg1"]=[[换人]],["arg2"]=[[sy6npc_07]],["arg3"]=[[sy6npc_07a]],["id"]=[[rlt_sy6change01]]},["rlt_sy6change02"]={["arg1"]=[[换人]],["arg2"]=[[sy6npc_01]],["arg3"]=[[sy6npc_01a]],["id"]=[[rlt_sy6change02]]},["rlt_sy6change03"]={["arg1"]=[[换人]],["arg2"]=[[sy6npc_09]],["arg3"]=[[sy6npc_09a]],["id"]=[[rlt_sy6change03]]},["rlt_sy6change04"]={["arg1"]=[[换人]],["arg2"]=[[sy6npc_09a]],["arg3"]=[[sy6npc_09]],["id"]=[[rlt_sy6change04]]},["rlt_sy6change05"]={["arg1"]=[[换人]],["arg2"]=[[sy6npc_01a]],["arg3"]=[[sy6npc_01b]],["id"]=[[rlt_sy6change05]]},["rlt_sy6change06"]={["arg1"]=[[换人]],["arg2"]=[[sy6npc_07b]],["arg3"]=[[sy6npc_07]],["id"]=[[rlt_sy6change06]]},["rlt_sy6choice01"]={["arg1"]=[[弹出按钮选择框]],["arg2"]=[[YEL少侠，想买什么样式的衣服？我这什么款式都有，保准有适合你的。]],["arg3"]=[[锦衣1000碎银]],["arg4"]=[[sy6jiujgj01]],["id"]=[[rlt_sy6choice01]]},["rlt_sy6gushi01"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL阿珍：这是你需要的杜鹃花，现在能用的就这么多了。;YEL阿珍：不过这花现在还不能给你，你需要回答我一个问题。;YEL阿珍：我这位姐妹总说杜鹃花开，素雅而纯洁。和她的姿容最为搭配，今日你来说说，这盛开的杜鹃花更配我们两个谁？]],["arg3"]=[[2;2;2]],["id"]=[[rlt_sy6gushi01]]},["rlt_sy6iteams01"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[syiteams06]],["arg3"]=1,["id"]=[[rlt_sy6iteams01]]},["rlt_sy6iteams04"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[syiteams07]],["arg3"]=1,["id"]=[[rlt_sy6iteams04]]},["rlt_sy6iteams05"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[money]],["arg3"]=-1000,["id"]=[[rlt_sy6iteams05]]},["rlt_sy6jiujgj01"]={["arg1"]=[[结果集]],["arg2"]=[[sy6iteams04;sy6iteams05;sy6change04]],["id"]=[[rlt_sy6jiujgj01]]},["rlt_sy6jiujgj02"]={["arg1"]=[[结果集]],["arg2"]=[[sy6change02;sy6text04;sy6iteams01;sy6jtbj03;delete]],["id"]=[[rlt_sy6jiujgj02]]},["rlt_sy6jiujgj04"]={["arg1"]=[[结果集]],["arg2"]=[[sy6text05;syrenwujindubj06;syrenwujieshubj;sy6change05]],["id"]=[[rlt_sy6jiujgj04]]},["rlt_sy6jtbj01"]={["arg1"]=[[地图标记设置]],["arg2"]=[[21手艺人称赞阿珍]],["arg3"]=1,["id"]=[[rlt_sy6jtbj01]]},["rlt_sy6jtbj02"]={["arg1"]=[[地图标记设置]],["arg2"]=[[21手艺人称赞如花]],["arg3"]=1,["id"]=[[rlt_sy6jtbj02]]},["rlt_sy6jtbj03"]={["arg1"]=[[地图标记设置]],["arg2"]=[[21手艺人交付锦衣]],["arg3"]=1,["id"]=[[rlt_sy6jtbj03]]},["rlt_sy6songli01"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[syiteams07,1]],["arg3"]=[[sy6jiujgj02]],["arg4"]=[[sy6text07]],["id"]=[[rlt_sy6songli01]]},["rlt_sy6songli03"]={["arg1"]=[[送礼条件结果]],["arg2"]=[[syiteams06,1]],["arg3"]=[[sy6jiujgj04]],["arg4"]=[[sy6text06]],["id"]=[[rlt_sy6songli03]]},["rlt_sy6text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL你如约来到白秋笙院落，随后阿珍带着整理好的一簇杜鹃花，和一位与她年纪相仿的女子进入院中。]],["id"]=[[rlt_sy6text01]]},["rlt_sy6text02"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL阿珍：哎呦~少侠这是哪的话，虽说我阿珍天生姿容俊美，堪比国色天香。但今日听少侠如此称誉小女子，还是有些羞涩的。既然如此，这杜鹃花便便交付于你，如还有需要随时来找我便是。
CYN阿珍被夸得沾沾自喜，手舞足蹈的拉着被气得脸色通红的如花离开了。]],["id"]=[[rlt_sy6text02]]},["rlt_sy6text03"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL阿珍：哼！我看你就是鼠目寸光！她那里比我更配如此美艳的花朵？我看，就算是不得见光的地鼠都要比你的眼光好上几分！
YEL阿珍：哼！要想得到这些花，你就去芳琴那里给我买一件锦衣赔罪！否则，姑奶奶扔了都不会给你！]],["id"]=[[rlt_sy6text03]]},["rlt_sy6text04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL阿珍：哼！想不到你长了双如此拙劣的眼睛，竟然能买来这么漂亮的锦衣，看在衣服的面子上，今天的事情就算了。YEL
阿珍：这是你要的花，姑奶奶可告诉你，我这的杜鹃花只能给你这么多。如果不够，不好意思，本姑奶奶不伺候了！
CYN阿珍将手中的花丢给你，随后气呼呼的拉着还在偷笑的如花离开了。]],["id"]=[[rlt_sy6text04]]},["rlt_sy6text05"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：嗯，这些杜鹃花开的很好，色泽浓厚。阿珍在种花的造诣上确实厉害。
YEL白秋笙：今日老夫将这些花晒干，你明日再来，我教你制作颜料。]],["id"]=[[rlt_sy6text05]]},["rlt_sy6text06"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：杜鹃花呢？]],["id"]=[[rlt_sy6text06]]},["rlt_sy6text07"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL阿珍：我的锦衣呢？]],["id"]=[[rlt_sy6text07]]},["rlt_sy6text08"]={["arg1"]=[[弹出文本]],["arg2"]=[[碎银不足]],["id"]=[[rlt_sy6text08]]},["rlt_sy7addnpc01"]={["arg1"]=[[添加人物]],["arg2"]=[[sy7npc_01]],["id"]=[[rlt_sy7addnpc01]]},["rlt_sy7addnpc02"]={["arg1"]=[[添加人物]],["arg2"]=[[syzhizuotai01]],["id"]=[[rlt_sy7addnpc02]]},["rlt_sy7addnpc03"]={["arg1"]=[[添加人物]],["arg2"]=[[syzhizuotai02]],["id"]=[[rlt_sy7addnpc03]]},["rlt_sy7addnpc04"]={["arg1"]=[[添加人物]],["arg2"]=[[syzhizuotai03]],["id"]=[[rlt_sy7addnpc04]]},["rlt_sy7addnpc04a"]={["arg1"]=[[添加人物]],["arg2"]=[[syzhizuotai03a]],["id"]=[[rlt_sy7addnpc04a]]},["rlt_sy7addnpc05"]={["arg1"]=[[添加人物]],["arg2"]=[[sy7npc_01b]],["id"]=[[rlt_sy7addnpc05]]},["rlt_sy7addnpc06"]={["arg1"]=[[添加人物]],["arg2"]=[[sy7npc_01c]],["id"]=[[rlt_sy7addnpc06]]},["rlt_sy7change01"]={["arg1"]=[[换人]],["arg2"]=[[sy7npc_01]],["arg3"]=[[sy7npc_01a]],["id"]=[[rlt_sy7change01]]},["rlt_sy7change02"]={["arg1"]=[[换人]],["arg2"]=[[sy7npc_01a]],["arg3"]=[[sy7npc_01b]],["id"]=[[rlt_sy7change02]]},["rlt_sy7change03"]={["arg1"]=[[换人]],["arg2"]=[[sy7npc_01b]],["arg3"]=[[sy7npc_01c]],["id"]=[[rlt_sy7change03]]},["rlt_sy7gushi01"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL白秋笙：今日，老夫就传授你制作脸谱的工序。老夫只说一遍，你要记好了。;YEL白秋笙：对了，陈平安有事先离开了，让我转告你，等你做完脸谱就送于他家，他会给你报酬。;YEL白秋笙：你准备好了就告诉我老夫，老夫说的顺序你要给我好好记住！]],["arg3"]=[[2;2]],["id"]=[[rlt_sy7gushi01]]},["rlt_sy7gushi02"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL白秋笙：制作脸谱首先要将选好的木料处理，雕刻出来。;YEL白秋笙:然后将晒干备用的花研磨成粉，制作颜料。;YEL白秋笙：最后也是最重要的一步，用大小不同的毛笔将图案画在雕刻好的木料上最后风干。;YEL白秋笙：这便是制作脸谱最基础的工序，如果记好了就开始着手制作吧。]],["arg3"]=[[2;2;2;2]],["id"]=[[rlt_sy7gushi02]]},["rlt_sy7gushi03"]={["arg1"]=[[副本故事]],["arg2"]=[[CYN你将磨好的花粉溶于染台上的油性液体中充分搅拌，很快混合物呈现出了鲜丽的色彩。你用染台上的各种大小、形状不同的毛笔沾着制作的颜料均匀的涂抹与雏形脸谱上。;CYN不多时，夹在染台上的雏形脸谱在各种鲜艳色彩的衬托下变得精美无比。;CYN你完成最后一步制作工序后稍作修饰便决定回去交差。]],["arg3"]=[[2;2;2]],["id"]=[[rlt_sy7gushi03]]},["rlt_sy7renwubj01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人制作步骤]],["arg3"]=1,["id"]=[[rlt_sy7renwubj01]]},["rlt_sy7renwubj01q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人制作步骤]],["id"]=[[rlt_sy7renwubj01q]]},["rlt_sy7renwubj02"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人使用石臼]],["arg3"]=1,["id"]=[[rlt_sy7renwubj02]]},["rlt_sy7renwubj02q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人使用石臼]],["id"]=[[rlt_sy7renwubj02q]]},["rlt_sy7renwubj03"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人使用雕刻台]],["arg3"]=1,["id"]=[[rlt_sy7renwubj03]]},["rlt_sy7renwubj03q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人使用雕刻台]],["id"]=[[rlt_sy7renwubj03q]]},["rlt_sy7renwubj04"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人使用染台]],["arg3"]=1,["id"]=[[rlt_sy7renwubj04]]},["rlt_sy7renwubj04q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人使用染台]],["id"]=[[rlt_sy7renwubj04q]]},["rlt_sy7renwubj05"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人失败脸谱]],["arg3"]=1,["id"]=[[rlt_sy7renwubj05]]},["rlt_sy7renwubj05q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人失败脸谱]],["id"]=[[rlt_sy7renwubj05q]]},["rlt_sy7renwubj06"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人成功脸谱]],["arg3"]=1,["id"]=[[rlt_sy7renwubj06]]},["rlt_sy7renwubj06q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人成功脸谱]],["id"]=[[rlt_sy7renwubj06q]]},["rlt_sy7text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：嗯？老夫都说了让你好好记住，真是榆木脑袋！简单来说，雕刻木料成型，研磨花瓣成粉，上色。真是朽木不可雕也。]],["id"]=[[rlt_sy7text01]]},["rlt_sy7text02"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：嗯，不错不错。你这家伙在老夫的指导下也做得有模有样嘛。今日你可以回去休息了，明日再来老夫这里吧。]],["id"]=[[rlt_sy7text02]]},["rlt_sy7text03"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：我不是告诉了你制作流程么？怎么不按照我说的做？你看现在这个成品像什么样子？也罢，今日你就先回去吧，明日来了在说后面的，真是朽木不可雕也。]],["id"]=[[rlt_sy7text03]]},["rlt_sy7text04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：回去吧，今日你能按照老夫的要求完成工序值得赞许，明日再来吧。]],["id"]=[[rlt_sy7text04]]},["rlt_sy7text05"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：你还不回去留在这干什么？]],["id"]=[[rlt_sy7text05]]},["rlt_sy7text06"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN用于研磨的工具，但用途你还不知道，等学会了再用吧。]],["id"]=[[rlt_sy7text06]]},["rlt_sy7text07"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN似乎是用于加工木材的工具，但用法你还不知道，等学会在用吧。]],["id"]=[[rlt_sy7text07]]},["rlt_sy7text08"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN你将晾干的花瓣放入石臼中，同时还用石棒将其碾碎研磨成粉。不多时，备用的花瓣如数变成石锅中的细粉。]],["id"]=[[rlt_sy7text08]]},["rlt_sy7text09"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN似乎没有可用的材料。]],["id"]=[[rlt_sy7text09]]},["rlt_sy7text10"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN你将准备好的枣木置于台上，将其固定后用工具将其切割、雕刻、打磨、抛光，得到了一个还算满意的脸谱雏形。]],["id"]=[[rlt_sy7text10]]},["rlt_sy7text12"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN台子上摆满各种各样的毛笔，似乎是用于绘制的工具，但用法你还不知道，等学会了在用吧。]],["id"]=[[rlt_sy7text12]]},["rlt_sy7text13"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN步骤似乎错了，不过你还是做出了一幅脸谱，只不过看起来有些奇怪，并不是很完美。]],["id"]=[[rlt_sy7text13]]},["rlt_sy7text14"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN步骤真的是这样的么?]],["id"]=[[rlt_sy7text14]]},["rlt_sy8addnpc01"]={["arg1"]=[[添加人物]],["arg2"]=[[sy8npc_01]],["id"]=[[rlt_sy8addnpc01]]},["rlt_sy8addnpc02"]={["arg1"]=[[添加人物]],["arg2"]=[[sy8npc_01c]],["id"]=[[rlt_sy8addnpc02]]},["rlt_sy8addnpc03"]={["arg1"]=[[添加人物]],["arg2"]=[[sy8npc_01d]],["id"]=[[rlt_sy8addnpc03]]},["rlt_sy8addnpc04"]={["arg1"]=[[添加人物]],["arg2"]=[[sy8npc_01e]],["id"]=[[rlt_sy8addnpc04]]},["rlt_sy8change01"]={["arg1"]=[[换人]],["arg2"]=[[sy8npc_01]],["arg3"]=[[sy8npc_01a]],["id"]=[[rlt_sy8change01]]},["rlt_sy8change02"]={["arg1"]=[[换人]],["arg2"]=[[sy8npc_01]],["arg3"]=[[sy8npc_01b]],["id"]=[[rlt_sy8change02]]},["rlt_sy8change03"]={["arg1"]=[[换人]],["arg2"]=[[sy8npc_01a]],["arg3"]=[[sy8npc_01c]],["id"]=[[rlt_sy8change03]]},["rlt_sy8change04"]={["arg1"]=[[换人]],["arg2"]=[[sy8npc_01b]],["arg3"]=[[sy8npc_01d]],["id"]=[[rlt_sy8change04]]},["rlt_sy8change05"]={["arg1"]=[[换人]],["arg2"]=[[sy8npc_01d]],["arg3"]=[[sy8npc_01e]],["id"]=[[rlt_sy8change05]]},["rlt_sy8choice01"]={["arg1"]=[[弹出按钮选择框]],["arg2"]=[[你选哪个名字？]],["arg3"]=[[秋色残阳,云海碧天,夜半寒月]],["arg4"]=[[sy8jiujgj01,sy8jiujgj02,sy8jiujgj03]],["id"]=[[rlt_sy8choice01]]},["rlt_sy8choice02"]={["arg1"]=[[弹出按钮选择框]],["arg2"]=[[你选哪个名字？]],["arg3"]=[[落尘凡,简面生,半月谱]],["arg4"]=[[sy8jiujgj04,sy8jiujgj05,sy8jiujgj06]],["id"]=[[rlt_sy8choice02]]},["rlt_sy8gushi01"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL白秋笙：昨日你做的脸谱颜料已经风干，虽然做出来了，但是比老夫我做的还是相差甚远。;YEL白秋笙：毕竟这是你制作的第一个成品，老夫就帮你取个名字吧。;YEL白秋笙：从你这副脸谱的风格来看，老夫倒是想了三个名字供你选择。第一个名字叫“秋色残阳”。;YEL白秋笙：第二个名字叫“云海碧天”。;YEL白秋笙：第三个名字是“夜半寒月”。;YEL白秋笙：你考虑一下选一个吧。]],["arg3"]=[[2;2;2;2;2;2]],["id"]=[[rlt_sy8gushi01]]},["rlt_sy8gushi02"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL白秋笙：昨日你上的色已经干了，让你不按照老夫说的做！看看像什么样子！;CYN因为昨日制作工序中流程步骤没有按照白秋笙所说的做，所以导致风干后的颜料有许多瑕疵。;YEL白秋笙：唉，罢了罢了，既然做出来了就取个名字吧。老夫想了三个，你选一个吧。;YEL白秋笙：第一个叫“落尘凡”。;YEL白秋笙：第二个叫“简面生”。;YEL白秋笙：第三个就叫“半月谱”。]],["arg3"]=[[2;2;2;2;2;2]],["id"]=[[rlt_sy8gushi02]]},["rlt_sy8jiujgj01"]={["arg1"]=[[结果集]],["arg2"]=[[sy8renwubj01;sy8renwubj04;syrenwujieshubj;syrenwujindubj08;sy8text01;sy8change03]],["id"]=[[rlt_sy8jiujgj01]]},["rlt_sy8jiujgj02"]={["arg1"]=[[结果集]],["arg2"]=[[sy8renwubj02;sy8renwubj04;syrenwujieshubj;syrenwujindubj08;sy8text01;sy8change03]],["id"]=[[rlt_sy8jiujgj02]]},["rlt_sy8jiujgj03"]={["arg1"]=[[结果集]],["arg2"]=[[sy8renwubj03;sy8renwubj04;syrenwujieshubj;syrenwujindubj08;sy8text01;sy8change03]],["id"]=[[rlt_sy8jiujgj03]]},["rlt_sy8jiujgj04"]={["arg1"]=[[结果集]],["arg2"]=[[sy8renwubj05;sy8text02;sy8renwubj04;sy8change04]],["id"]=[[rlt_sy8jiujgj04]]},["rlt_sy8jiujgj05"]={["arg1"]=[[结果集]],["arg2"]=[[sy8renwubj06;sy8text02;sy8renwubj04;sy8change04]],["id"]=[[rlt_sy8jiujgj05]]},["rlt_sy8jiujgj06"]={["arg1"]=[[结果集]],["arg2"]=[[sy8renwubj07;sy8text02;sy8renwubj04;sy8change04]],["id"]=[[rlt_sy8jiujgj06]]},["rlt_sy8renwubj01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人手艺人剧情名字]],["arg3"]=[[秋色残阳]],["id"]=[[rlt_sy8renwubj01]]},["rlt_sy8renwubj01q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人手艺人剧情名字]],["id"]=[[rlt_sy8renwubj01q]]},["rlt_sy8renwubj02"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人手艺人剧情名字]],["arg3"]=[[云海碧天]],["id"]=[[rlt_sy8renwubj02]]},["rlt_sy8renwubj03"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人手艺人剧情名字]],["arg3"]=[[夜半寒月]],["id"]=[[rlt_sy8renwubj03]]},["rlt_sy8renwubj04"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人名字选择]],["arg3"]=1,["id"]=[[rlt_sy8renwubj04]]},["rlt_sy8renwubj04q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人名字选择]],["id"]=[[rlt_sy8renwubj04q]]},["rlt_sy8renwubj05"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人手艺人剧情名字]],["arg3"]=[[落尘凡]],["id"]=[[rlt_sy8renwubj05]]},["rlt_sy8renwubj06"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人手艺人剧情名字]],["arg3"]=[[简面生]],["id"]=[[rlt_sy8renwubj06]]},["rlt_sy8renwubj07"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人手艺人剧情名字]],["arg3"]=[[半月谱]],["id"]=[[rlt_sy8renwubj07]]},["rlt_sy8renwubj08"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人忍受白秋笙]],["arg3"]=1,["id"]=[[rlt_sy8renwubj08]]},["rlt_sy8renwubj08q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人忍受白秋笙]],["id"]=[[rlt_sy8renwubj08q]]},["rlt_sy8renwubj09"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人与白秋笙争执]],["arg3"]=1,["id"]=[[rlt_sy8renwubj09]]},["rlt_sy8renwubj09q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人与白秋笙争执]],["id"]=[[rlt_sy8renwubj09q]]},["rlt_sy8text01"]={["arg1"]=[[手艺人剧情文本输出]],["arg2"]=[[YEL白秋笙：$name么？嗯...果然选的是这个名字么，哈哈哈，不错不错！老夫也很中意此名！;YEL白秋笙：今日你先回去吧，明日来此，把你做的$name展示出去。毕竟手艺人的作品是要被大众所喜欢的，让群众去评价作品无疑是最好的选择。]],["id"]=[[rlt_sy8text01]]},["rlt_sy8text02"]={["arg1"]=[[手艺人剧情文本输出]],["arg2"]=[[YEL白秋笙：$name么？哼，真是有点可惜了这个名字。]],["id"]=[[rlt_sy8text02]]},["rlt_sy8text03"]={["arg1"]=[[手艺人剧情文本输出]],["arg2"]=[[YEL白秋笙:今天就到这吧，明日你再来，我会把你做的这个$name展示在大众面前，做的好不好让大家评判吧。]],["id"]=[[rlt_sy8text03]]},["rlt_sy8text04"]={["arg1"]=[[手艺人剧情文本输出]],["arg2"]=[[YEL白秋笙：哼！让你按照老夫的方法做你偏不听，做出来的东西如此不堪，老夫取的$name这个名字你有什么异议？老夫还没说你糟蹋了这个名字呢！]],["id"]=[[rlt_sy8text04]]},["rlt_sy8text05"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：嗯？你怎么还不回去？我要准备明天展示需要的东西，你在这太碍眼了，明天准备好了再来吧。]],["id"]=[[rlt_sy8text05]]},["rlt_sy8text06"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：你走吧，这件事就到此为止了，明日你再来吧。]],["id"]=[[rlt_sy8text06]]},["rlt_sy9addnpc01"]={["arg1"]=[[添加人物]],["arg2"]=[[sy9npc_01]],["id"]=[[rlt_sy9addnpc01]]},["rlt_sy9addnpc02"]={["arg1"]=[[添加人物]],["arg2"]=[[sy9npc_10]],["id"]=[[rlt_sy9addnpc02]]},["rlt_sy9addnpc03"]={["arg1"]=[[添加人物]],["arg2"]=[[sy9npc_01a]],["id"]=[[rlt_sy9addnpc03]]},["rlt_sy9addnpc06"]={["arg1"]=[[添加人物]],["arg2"]=[[sy9npc_14]],["id"]=[[rlt_sy9addnpc06]]},["rlt_sy9addnpc07"]={["arg1"]=[[添加人物]],["arg2"]=[[sy9npc_01c]],["id"]=[[rlt_sy9addnpc07]]},["rlt_sy9addnpc09"]={["arg1"]=[[添加人物]],["arg2"]=[[sywuping01]],["id"]=[[rlt_sy9addnpc09]]},["rlt_sy9addnpc10"]={["arg1"]=[[添加人物]],["arg2"]=[[sy9npc_01e]],["id"]=[[rlt_sy9addnpc10]]},["rlt_sy9addnpc11"]={["arg1"]=[[添加人物]],["arg2"]=[[syjiangli03]],["id"]=[[rlt_sy9addnpc11]]},["rlt_sy9addnpc12"]={["arg1"]=[[添加人物]],["arg2"]=[[syjiangli03a]],["id"]=[[rlt_sy9addnpc12]]},["rlt_sy9change01"]={["arg1"]=[[换人]],["arg2"]=[[syjiangli03]],["arg3"]=[[syjiangli03a]],["id"]=[[rlt_sy9change01]]},["rlt_sy9change02"]={["arg1"]=[[换人]],["arg2"]=[[sy9npc_01]],["arg3"]=[[sy9npc_01a]],["id"]=[[rlt_sy9change02]]},["rlt_sy9change03"]={["arg1"]=[[换人]],["arg2"]=[[sywuping01]],["arg3"]=[[sywuping02]],["id"]=[[rlt_sy9change03]]},["rlt_sy9change04"]={["arg1"]=[[换人]],["arg2"]=[[sywuping02]],["arg3"]=[[sywuping01]],["id"]=[[rlt_sy9change04]]},["rlt_sy9change05"]={["arg1"]=[[换人]],["arg2"]=[[sy9npc_01a]],["arg3"]=[[sy9npc_01c]],["id"]=[[rlt_sy9change05]]},["rlt_sy9change06"]={["arg1"]=[[换人]],["arg2"]=[[sy9npc_10]],["arg3"]=[[sy9npc_11]],["id"]=[[rlt_sy9change06]]},["rlt_sy9change07"]={["arg1"]=[[换人]],["arg2"]=[[sy9npc_11]],["arg3"]=[[sy9npc_13]],["id"]=[[rlt_sy9change07]]},["rlt_sy9change08"]={["arg1"]=[[换人]],["arg2"]=[[sy9npc_13]],["arg3"]=[[sy9npc_12]],["id"]=[[rlt_sy9change08]]},["rlt_sy9change09"]={["arg1"]=[[换人]],["arg2"]=[[sy9npc_12]],["arg3"]=[[sy9npc_14]],["id"]=[[rlt_sy9change09]]},["rlt_sy9gushi01"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL白秋笙：嗯，你来了。从你跟我学这门手艺到现在，已经过去了这些时日，昨夜老夫思考良久后这才做出决定。;白秋笙：看来学手艺这件事，并不适合你。;白秋笙：那边箱子里的东西送给你了，以后你可以不用再来此找老夫了。你我缘分已尽，用里面的东西换点你用得上的吧，如果还需此物就去秦高松那问问吧。江湖路远，保重。;CYN白秋笙指了指摊位旁的精致木箱，转身进了屋子将门紧紧关闭不在说话。]],["arg3"]=[[2;2;2;2]],["id"]=[[rlt_sy9gushi01]]},["rlt_sy9renwubj01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人开始吆喝]],["arg3"]=1,["id"]=[[rlt_sy9renwubj01]]},["rlt_sy9renwubj01q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人开始吆喝]],["id"]=[[rlt_sy9renwubj01q]]},["rlt_sy9renwubj02"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人金老爷出现]],["arg3"]=1,["id"]=[[rlt_sy9renwubj02]]},["rlt_sy9renwubj02q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人金老爷出现]],["id"]=[[rlt_sy9renwubj02q]]},["rlt_sy9text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：来了就别愣着了，摊位准备好了，赶紧吆喝吆喝，看看你做的东西别人是怎么评价的。]],["id"]=[[rlt_sy9text01]]},["rlt_sy9text02"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：快点吆喝吆喝。]],["id"]=[[rlt_sy9text02]]},["rlt_sy9text03"]={["arg1"]=[[手艺人剧情文本输出]],["arg2"]=[[YEL陆仁贾：哼，这东西看起来也不怎么样啊，$name是这个东西的名字？真是糟蹋这几个字了。;YEL陆仁贾：我还以为是啥好东西呢，搞这么大阵仗，真没意思。]],["id"]=[[rlt_sy9text03]]},["rlt_sy9text04"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL包汇易：先不论这个东西好不好，单说这个名字我觉到到蛮有诗情画意的。
YEL包汇易：我要赶去买药，就不在此停留了，告辞。]],["id"]=[[rlt_sy9text04]]},["rlt_sy9text05"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘茂柄：我觉得这东西只不过是加厚点的面具，戴又不能戴，弄个面具摆着看岂不是多余？
YEL刘茂柄：哼，要我说，做这东西就是在浪费时间和材料，如此破烂不堪的东西倒不如劈了烧掉！
YEL刘茂柄：看什么！老子说的不对么？这种没用的垃圾就应该劈了烧柴！不服你打我啊！]],["id"]=[[rlt_sy9text05]]},["rlt_sy9text06"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘茂柄：哼，想不到还是个练家子，道不同不相为谋。
CYN刘茂柄吃了瘪灰溜溜跑了。]],["id"]=[[rlt_sy9text06]]},["rlt_sy9text07"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐风定：在下到觉得着脸谱做的很不错，从基础的形状来看，虽说雕刻之人有些生涩，但还是能看出一些手上功夫的底蕴。
YEL唐风定：着脸谱之上的色彩，虽不能说完美，但从这淡淡的幽香就知道选用的材料一定是上好的。
YEL唐风定：在下还有些琐事在身，就不在此耽搁了，告辞。]],["id"]=[[rlt_sy9text07]]},["rlt_sy9text08"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL金老爷：今日逛了许久，你们这个东西我倒是很感兴趣，不知售价多少，还请摊主告知，我金某人绝不还价。
YEL金老爷：如若摊主今日无法定夺，那金某人明日再来。
YEL金老爷：明日我会带足银两前来，还望摊主给出一个合理的价钱。]],["id"]=[[rlt_sy9text08]]},["rlt_sy9text09"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL白秋笙：既然有人来了你就去询问询问别人的看法吧。]],["id"]=[[rlt_sy9text09]]},["rlt_sy9text11"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN你打开箱子，取出里面的东西。]],["id"]=[[rlt_sy9text11]]},["rlt_sy9text12"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN书信内容：既然你与我等手艺人一脉无缘，老夫也不再强求。这些东西放在我这没有用处，我便赠送与你，希望你用这些东西去老人峰的刘南春处换取需要的物品，如果还需此物不如去秦高松那问问。江湖路远，珍重。]],["id"]=[[rlt_sy9text12]]},["rlt_sy9text13"]={["arg1"]=[[副本故事]],["arg2"]=[[CYN你站在摊位上吆喝了几声，人纷纷聚拢过来看着出自你手的脸谱窃窃私语。;YEL陆仁贾：这做的是啥呀？;YEL包汇易：看起来应该是某种手工艺品吧。;YEL刘茂柄：啥工艺品，那不就是面具么，不过上面的绘图倒是挺新鲜。;YEL唐风定：哼，你们几个粗人懂个屁。人家这是做的脸谱，就是把涂在脸上的彩绘画在木质的雏具上，这样就能保存下来。]],["arg3"]=[[2;2;2;2;2]],["id"]=[[rlt_sy9text13]]},["rlt_syblchange"]={["arg1"]=[[换人]],["arg2"]=[[sybulingnpc01]],["arg3"]=[[sybulingnpc]],["id"]=[[rlt_syblchange]]},["rlt_syjianglingqu01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人奖励领取]],["arg3"]=1,["id"]=[[rlt_syjianglingqu01]]},["rlt_syjianglingqu01q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人奖励领取]],["id"]=[[rlt_syjianglingqu01q]]},["rlt_syjianglingqu02"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人奖励领取]],["arg3"]=1,["id"]=[[rlt_syjianglingqu02]]},["rlt_syjianglingqu03"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人奖励领取]],["arg3"]=1,["id"]=[[rlt_syjianglingqu03]]},["rlt_syjianglingqu04"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人奖励领取]],["arg3"]=1,["id"]=[[rlt_syjianglingqu04]]},["rlt_syjianglingqu05"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人奖励领取]],["arg3"]=1,["id"]=[[rlt_syjianglingqu05]]},["rlt_syjianglingqu06"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人奖励领取]],["arg3"]=1,["id"]=[[rlt_syjianglingqu06]]},["rlt_syjieju01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人第一种结局]],["arg3"]=1,["id"]=[[rlt_syjieju01]]},["rlt_syjieju01q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人第一种结局]],["id"]=[[rlt_syjieju01q]]},["rlt_syjieju02"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人第二种结局]],["arg3"]=1,["id"]=[[rlt_syjieju02]]},["rlt_syjieju02q"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人第二种结局]],["id"]=[[rlt_syjieju02q]]},["rlt_syjieju03"]={["arg1"]=[[玩家标记设置